import json
schedule=[
("cobalt",[0,1,2,3,4],1320,360),
("reed",[0,2,4],1380,180),
("plum",[1,3,5],30,150),
("shell",[6],1350,90),
("gold",[0],0,90),
("elm",[5],60,180)]
def correct(d,m,first=False):
    hits=[]
    t=d*1440+m
    for i,(r,days,s,e) in enumerate(schedule):
        duration=(e-s)%1440
        if any(0 <= (t-(day*1440+s))%10080 < duration for day in days):
            hits.append((duration,i,r))
    if not hits: return "idle"
    return min(hits,key=(lambda h:h[1]) if first else (lambda h:(h[0],h[1])))[2]
def faulty_day(d,m):
    hits=[]
    for i,(r,days,s,e) in enumerate(schedule):
        clock=(s<=m<e) if s<e else (m>=s or m<e)
        if d in days and clock:
            hits.append(((e-s)%1440,i,r))
    return min(hits)[2] if hits else "idle"
jobs=[(1,29),(1,30),(1,150),(1,179),(1,180),(5,59),(5,60),(5,149),(5,150),(5,180),(6,1349),(6,1350),(0,0),(0,89),(0,90),(2,359),(2,360),(4,1380)]
w={}
for name in ["day_owner","first_match"]:
    for d in range(7):
        for m in range(1440):
            expected=correct(d,m)
            day=faulty_day(d,m)
            first=correct(d,m,True)
            isolated=(day!=expected and first==expected) if name=="day_owner" else (first!=expected and day==expected)
            if isolated:
                w[name]={"job":{"receiver":{"day":d,"minute":m}},"expected":expected}
                break
        if name in w: break
assert set(w)=={"day_owner","first_match"}
for name,entry in w.items():
    d=entry["job"]["receiver"]["day"];m=entry["job"]["receiver"]["minute"]
    assert 0<=d<=6 and 0<=m<=1439
    ex=entry["expected"]
    assert ex==correct(d,m)
    assert (faulty_day(d,m)!=ex)==(name=="day_owner")
    assert (correct(d,m,True)!=ex)==(name=="first_match")
result={"routes":[correct(d,m) for d,m in jobs],"witnesses":w}
assert len(result["routes"])==18
print(json.dumps(result,separators=(",",":")))

